//! P09 counted loops (docs/invariant-synthesis.md): one loop per shape of the counted family. Each
//! loop's invariant and measure are generated by air2lean-invgen; Proof.lean walks them with fsym.
//! Every add is checked: it panics on overflow.

/// Counts `i` down from `n` to 0 (`i > 0`, `i -= 1`) and adds 3 to `acc.*` each time.
export fn down(acc: *u64, n: u32) void {
    var i: u32 = n;
    while (i > 0) : (i -= 1) acc.* += 3;
}

/// Counts `i` up to `n` under a `!=` guard: `n` iterations.
export fn upNe(acc: *u64, n: u32) void {
    var i: u32 = 0;
    while (i != n) : (i += 1) acc.* += 1;
}

/// Counts `i` up to `n` under a `<=` guard: `n + 1` iterations.
export fn upLe(acc: *u64, n: u32) void {
    var i: u32 = 0;
    while (i <= n) : (i += 1) acc.* += 1;
}

/// Counts `i` up to the length of `xs`: a slice-length bound.
pub fn lenCount(acc: *u64, xs: []const u32) void {
    var i: usize = 0;
    while (i < xs.len) : (i += 1) acc.* += 1;
}

/// Counts `i` up to `lim.*`, read in every iteration: a bound behind a pointer.
export fn readBound(acc: *u64, lim: *const u32) void {
    var i: u32 = 0;
    while (i < lim.*) : (i += 1) acc.* += 1;
}

/// Adds 1 to `acc[0]` and 2 to `acc[1]` in each of `n` iterations: cells at offsets.
export fn pairAt(acc: *[2]u64, n: u32) void {
    var i: u32 = 0;
    while (i < n) : (i += 1) {
        acc[0] += 1;
        acc[1] += 2;
    }
}

/// Adds `i` to `acc.*` for each `i < n`: a sum that depends on the counter.
export fn tri(acc: *u64, n: u32) void {
    var i: u32 = 0;
    while (i < n) : (i += 1) acc.* += i;
}

comptime {
    _ = &lenCount;
}
